    exp1: "表見代理とは、代理権がないにもかかわらず代理権があるように見える外観が存在し、相手方がその外観を正当な理由（無過失）で信頼した場合に、本人に代理の効果を帰属させる制度。3類型：①代理権授与表示（代理権があると表示した）、②権限外の行為（基本代理権の範囲外）、③代理権消滅後の行為。",
