    exp1: "時効とは、一定期間の事実状態の継続を要件として、権利の取得（取得時効）または消滅（消滅時効）の効果を生じさせる制度。時効の利益は援用によって確定する。援用権者は時効によって直接利益を受ける者（債務者・保証人・物上保証人・後順位抵当権者等）。",
    exp2: "2020年民法改正で消滅時効の原則は「主観的起算点から5年または客観的起算点から10年」のいずれか早い方。時効の完成猶予（完成を一時ストップ）と更新（リセット）の区別も頻出。催告は6か月の完成猶予事由、確定判決は更新事由。",
    exp3: "「時効が完成＝自動的に効果発生」ではない。援用という意思表示が必要。逆に時効の利益を放棄することもできる（ただし時効完成前の放棄は不可）。",
