    exp1: "取得時効とは、他人の物を一定期間占有し続けることで所有権その他の権利を取得する制度。所有の意思・平穏・公然の占有を継続することが要件。善意無過失で10年間、悪意または有過失で20年間の占有継続で成立。占有開始時に善意無過失であればよく、途中で悪意になっても10年で成立する。",
