    exp1: "消滅時効とは、権利を行使しないまま一定期間が経過することで権利が消滅する制度。2020年民法改正後、債権の消滅時効は「権利を行使できることを知った時（主観的起算点）から5年」または「権利を行使できる時（客観的起算点）から10年」のいずれか早い方。旧法の賃料（1年）・工事代金（3年）等の短期時効は廃止された。",
    exp2: "不法行為による損害賠償請求権は「損害および加害者を知った時から3年（生命・身体は5年）」または「不法行為の時から20年」。この例外が試験頻出。また「時効の更新」と「完成猶予」の違いと各事由（承認・確定判決・催告等）も必須知識。",
    exp3: "改正後は短期時効が廃止されたため、旧法の数字（1年・2年・3年）を使うと誤り。すべて原則5年/10年に統一されたと覚える。\n\n**覚え方**\n消滅時効「知ったら5年・知らなくても10年」。知ってて放置は5年でアウト。",
