    exp1: "時効の援用とは、時効による利益を受ける意思を表示すること。時効の効力は援用によって確定する（援用がなければ裁判所は時効を考慮できない）。援用権者は時効によって直接利益を受ける者に限られる。主な援用権者：債務者、連帯保証人、物上保証人、後順位抵当権者、詐害行為の受益者など。",
    exp2: "「援用権者の範囲」が頻出。「直接利益を受ける者」に限定される。たとえば一般債権者は援用権者にならない（判例）。また時効利益の放棄は時効完成後のみ可能。完成前の放棄は不可（なぜなら放棄を強制される恐れがあるため）。放棄後は再度時効が進行する。",
    exp3: "援用と放棄は別物。援用＝時効の効果を使う意思表示、放棄＝時効の利益を捨てる意思表示。時効完成後に「払います」と承認した場合は時効利益の放棄と解される。",
