    exp1: "時効の完成猶予とは、時効の完成を一定期間引き延ばす制度（旧法の「停止」に相当）。主な事由：①催告（内容証明等）→6か月間猶予、②裁判上の請求・支払督促・調停など→手続終了まで猶予+終了後6か月、③仮差押え・仮処分→手続終了後6か月、④天災等（不可抗力）→障害消滅後3か月。猶予中に更新事由が生じると更新される。",
