    exp1: "物権とは、物を直接的・排他的に支配する権利。対世効（誰に対しても主張できる）と排他性（同一物上に同一内容の物権は二つ存在できない）を持つ。物権法定主義（民法に定めのない物権は創設不可）。種類：所有権・地上権・地役権・永小作権（用益物権）、留置権・先取特権・質権・抵当権（担保物権）。",
