    exp1: "物権変動とは、物権の発生・変更・消滅。不動産の物権変動は当事者間では意思表示のみで効力を生じるが（177条）、第三者に対抗するには登記が必要。二重譲渡で登記なき者は後登記者に対抗できない。「第三者」とは登記の欠缺を主張する正当な利益を有する第三者（背信的悪意者は第三者に含まれない）。",
    exp2: "「背信的悪意者」の論点が頻出。単なる悪意者は177条の第三者に含まれ、先に登記すれば勝つ。しかし「積極的妨害・いやがらせ目的」の背信的悪意者は登記があっても対抗できない（判例）。また相続・時効取得による物権変動と登記の関係も出題される。",
    exp3: "動産の物権変動の対抗要件は「引渡し」（178条）。登記ではない点に注意。不動産と動産で対抗要件が異なる。",
