    exp1: "対抗要件とは、すでに成立した権利を第三者に対して主張（対抗）するために必要な法的手続き。不動産物権変動の対抗要件は登記（民法177条）、動産は引渡し（178条）、債権譲渡は確定日付ある通知または承諾（467条）。賃借権の対抗要件は登記または建物の引渡し（借地借家法31条）。",
    exp2: "各権利の対抗要件を横断的に押さえることが宅建合格の鍵。特に「賃借権の対抗要件＝引渡し（登記不要）」は頻出。また対抗要件を備えた後に設定された権利には、対抗できる。仮登記は本登記の順位を保全する効力があり、本登記後は仮登記時の順位で対抗できる。",
    exp3: "対抗要件は「権利の発生」要件ではない。権利は意思表示で発生し、対抗要件は第三者への主張可否の問題。対抗要件がなくても当事者間では権利が有効に存在する。",
