    exp1: "所有権とは、法令の制限内において自由に物を使用・収益・処分できる権利（民法206条）。物権の中で最も強力かつ全面的な権利。所有権は永続し、消滅時効にかかることはない（ただし取得時効で喪失することはある）。共有の場合は持分という形で所有権が分割される。",
