    exp1: "共有とは、複数人が一つの物を持分によって共同所有する状態。各共有者は自己の持分を自由に処分できるが、共有物全体の処分には全員同意が必要。管理行為は持分の過半数で決定。保存行為（現状維持・修繕等）は各自単独で可能。分割請求はいつでもできる（不分割特約は5年以内で更新可）。",
