    exp1: "危険負担とは、双務契約で一方の債務が当事者双方の帰責事由なく履行不能になった場合、他方の反対給付債務をどう扱うかの問題。2020年民法改正で大きく変更。旧法→不動産売買は「債権者主義」（買主が危険負担）。改正後→「債務者主義」に統一（売主が危険負担）。買主は反対給付（代金支払）を拒絶できる。",
    exp2: "「改正前後の違い」が最重要。旧法では不動産売買で引渡前に滅失しても買主が代金を払う（債権者主義）→買主に酷と批判。改正後は債務者主義に統一→履行不能になった債務の債務者が危険を負担→売主が履行不能なら買主は代金支払を拒絶できる。この改正を知らないと旧法の知識で間違える。",
    exp3: "債権者（買主）の帰責事由で滅失した場合は例外。この場合は買主は代金支払義務を負う（帰責事由ある者が危険負担）。",
