    exp1: "相続とは、被相続人（死亡した人）の財産上の権利・義務を、相続人が包括的に承継する制度（民法896条）。不動産の所有権だけでなく、売買契約上の地位・ローン債務・賃貸借契約もすべて引き継ぐ。",
    exp2: "宅建試験では「相続人の範囲」「法定相続分」「遺言との関係」が主な出題ポイント。包括承継の意味は「プラスもマイナスも丸ごと」。相続放棄をすれば初めから相続人でなかったことになる（t057）。",
