    exp1: "法定相続分は民法900条が定める。配偶者と子が相続人なら配偶者1/2・子全体で1/2（子が複数なら均等）。配偶者と直系尊属（親）なら配偶者2/3・直系尊属1/3。配偶者と兄弟姉妹なら配偶者3/4・兄弟姉妹1/4。",
    exp2: "宅建試験では「誰と誰が相続人か」を特定してから相続分を計算する問題が頻出。相続人の組み合わせパターンを3パターン丸ごと暗記する。非嫡出子（認知された子）の相続分は嫡出子と同じ（2013年改正後）。",
    exp3: "「配偶者は常に1/2」と思いがち。相続人の組み合わせによって配偶者の割合は1/2・2/3・3/4と変わる。\n\n**覚え方** 「配偶者の相手が子→半分半分、親→倍もらい(2/3)、兄弟→3/4」と序列で覚える。",
