    exp1: "代襲相続とは、本来の相続人（被代襲者）が相続開始以前に死亡・相続欠格・廃除のいずれかに該当した場合に、その直系卑属（子・孫等）が代わりに相続する制度（民法887条）。兄弟姉妹が相続人の場合、代襲は1代限り（甥・姪まで）。",
