    exp1: "所有権保存登記とは、表題登記がされた不動産について初めて行う所有権の登記（不動産登記法74条）。これにより権利部甲区に最初の所有者が記録され、以後の所有権移転登記の出発点となる。申請義務はなく、登録免許税（t***）の課税対象。",
