    exp1: "専有部分とは、区分所有建物において構造上独立し、かつ住居・店舗等の用途に使用できる独立した部分（区分所有法2条3項）。壁・床・天井の内側の部分が専有部分とされることが多い。専有部分の所有権は区分所有者が単独で保有する。",
    exp2: "専有部分の内装変更は原則可能だが、管理規約でフローリングへの変更禁止・工事届出義務等を定める例が多い。構造に影響する工事（壁の撤去等）は共用部分に触れる可能性があり特に制限が厳しい。",
    exp3: "「専有部分は何でも自由」は誤り。管理規約・集会決議による制限が適用される。\n\n**覚え方** 「専有＝自分のもの、でも規約には従う」。マンションは共同生活、完全な自由はない。",
