    q: "次の状況に当てはまるのは？",
    choices: [{"text":"廊下・エントランスは法定共用部分であり、全区分所有者の共有となる","correct":true},{"text":"廊下・エントランスは管理会社の所有物である","correct":false,"hint":"共用部分は区分所有者全員の共有。管理会社は管理業務を委託されているだけ。"}],
    exp1: "共用部分は、廊下・階段・エレベーター・外壁等の複数の区分所有者が共有する部分（区分所有法4条）。「法定共用部分」（構造上当然に共用となる部分）と「規約共用部分」（規約で共用と定めた部分、例：管理人室）に分かれる。共用部分の変更には集会決議が必要。",
    exp2: "共用部分の持分割合は専有部分の床面積割合による（規約で別途定めることも可）。管理費・修繕積立金の負担割合にも影響する。共用部分を専有部分として処分することはできない。",
    exp3: "「規約共用部分は最初から共用部分だ」と思いがち。規約共用部分は登記しなければ善意の第三者に対抗できない（区分所有法4条2項）。\n\n**覚え方** 「法定共用＝構造上当然・規約共用＝決め事でそうした」。登記が必要かどうかで区別。",
