    exp1: "管理組合は区分所有法3条に基づき、建物・敷地・附属施設の管理のために区分所有者全員で構成される団体。加入に選択の余地はなく、区分所有者になった時点で自動的に構成員となる。管理組合は管理者（理事長等）を置くことができる。",
    exp2: "管理組合と管理会社（マンション管理業者）は別物。管理組合は区分所有者による自治組織、管理会社は管理組合から業務委託を受けた会社。管理費は管理組合に支払い、管理組合が管理会社に委託費を支払う流れ。",
    exp3: "「管理組合＝管理会社」と混同しがち。管理組合は区分所有者の自治組織、管理会社は委託先の民間企業。\n\n**覚え方** 「管理組合＝住民の自治会。管理会社＝雇われた専門業者」。区別して記憶する。",
