    keyword: "管理組合が定める自治ルール・特別決議で変更",
    scenario: "マンションの管理組合でペット禁止を定める規約の廃止が議題になった。規約を変更するにはどの程度の賛成が必要かで意見が割れている。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"規約の変更には区分所有者および議決権の各3/4以上（特別多数決議）が必要","correct":true},{"text":"規約の変更は過半数の賛成があれば行える","correct":false,"hint":"規約変更は特別決議（3/4以上）が必要。過半数の普通決議では不足。"}],
    exp1: "規約とは、管理組合が定める自治的なルール（区分所有法30条以下）。ペット飼育・騒音・共用部の使用等について細かく定めることができる。規約の設定・変更・廃止には区分所有者および議決権の各3/4以上の特別多数決議が必要（区分所有法31条）。",
    exp2: "規約は書面によって作成する必要があり（区分所有法30条3項）、管理者が保管・閲覧に供する義務を負う。規約に定めることで普通決議事項を特別決議事項に格上げすることも可能。規約で別段の定めができる事項も多い。",
    exp3: "「規約変更は過半数で可」は誤り。規約の設定・変更・廃止はすべて3/4以上の特別多数決議。\n\n**覚え方** 「規約変更＝3/4特別決議」。マンションのルール改正は全員の3/4が同意しないと変わらない。",
