    exp1: "集会は管理組合の最高意思決定機関であり、管理者（理事長）は少なくとも年1回開催する義務がある（区分所有法34条1項）。招集は原則として1〜2週間前に書面で通知。区分所有者の1/5以上の議決権を有する者が招集を請求することもできる。",
