    exp3: "「全員同意なら集会不要」は一部正しい。書面決議（全員同意）は可能だが、通常の集会省略はできない。\n\n**覚え方** 「集会＝年1回必ず。全員書面同意なら代替OK」。年に一度は民主主義を実践。",
