    exp1: "普通決議とは、区分所有者および議決権の各過半数により成立する決議（区分所有法39条1項）。管理委託契約の変更・規約の廃止（※規約変更は特別決議）等、通常の管理事項に適用される。「区分所有者の数」と「議決権の数」の両方で過半数が条件。",
    exp2: "議決権は専有部分の床面積の割合による（規約で別途定めることも可）。区分所有者が複数の住戸を持つ場合、その分の議決権を持つ。規約で普通決議の要件を加重することも可能。",
    exp3: "「出席者の過半数」と「区分所有者全体の過半数」を混同しがち。区分所有法上は「区分所有者の数」と「議決権の数」の各過半数が基本。\n\n**覚え方** 「普通決議＝人数×議決権の両方で1/2超え」。どちらか一方だけでは不足。",
