    exp1: "特別決議は区分所有者および議決権の各3/4以上の賛成が必要（区分所有法17条・31条）。規約の設定・変更・廃止、共用部分の重大な変更（形状・効用の著しい変更を伴うもの）等に適用される。30人中22人では22÷30≒0.733で3/4（0.75）に届かない。",
