    exp1: "建替え決議は区分所有者および議決権の各4/5以上の賛成が必要（区分所有法62条）。最も厳しい決議要件で、老朽化・危険化したマンションの建替えに適用される。35÷40＝0.875で4/5（0.80）以上のため有効。",
