    exp1: "普通借地権は、期間満了時に借地人が更新を請求した場合、または建物がある状態で期間満了後も継続使用した場合に、原則として更新される（法定更新・借地借家法5条）。地主が更新を拒絶するには「正当事由」が必要で、単なる「期間満了」だけでは拒絶できない。",
