    exp1: "混同とは、所有権とその目的物上の制限物権（地上権・抵当権等）が同一人に帰属した場合に、制限物権が消滅する制度（民法179条）。例外として、その制限物権が第三者の権利の目的になっている場合は消滅しない（第三者保護のため）。",
    exp2: "混同は債権の場面でも生じる（民法520条）。同一人が債権者・債務者になった場合、債権は消滅する（例：債権者が死亡して債務者が相続した場合）。混同による消滅は自動的（意思表示不要）。",
    exp3: "「混同があれば常に消滅」は誤り。第三者の権利の目的となっている制限物権は消滅しない例外がある。\n\n**覚え方** 「混同＝1人2役は成り立たない→権利消滅。ただし第三者が絡む場合は例外」。",
