    scenario: "不動産売買で、買主Eがまだ登記を備えていない間に、元売主Fが共謀してGに二重譲渡した。GはEが登記を持っていないことを知りながら、Eを困らせる目的で購入した。GはEに対して優先するか。",
    q: "次の状況に当てはまるのは？",
