    exp1: "民法177条は「不動産物権変動は登記なければ第三者に対抗できない」と定めるが、「第三者」には誰でも入るわけではない。判例は、登記のないことを知りながら（悪意）かつ積極的に害意を持って介入する者（背信的悪意者）を「第三者」から除外する。つまり登記がなくても背信的悪意者には対抗できる。",
    exp2: "背信的悪意者の判断は「単なる悪意（知っていた）」だけでは不足。積極的な害意・不正目的の介入が必要（判例）。Gのように「困らせる目的」で行動した場合は背信的悪意者。一方、単に「Eが買った事実を知っていた」だけの第三者は通常の悪意者として第三者に含まれる。",
    exp3: "「悪意者は第三者に該当しない」は誤り。単なる悪意（知っていた）は第三者に含まれる。除外されるのは「背信的悪意者」（害意付き悪意）のみ。\n\n**覚え方** 「背信的悪意者＝嫌がらせ目的で介入した者→登記なしでも負かせる」。普通の悪意とは別格。",
