    exp1: "宅建業法第33条により、宅建業者は未完成物件（開発許可・建築確認等の処分前）について広告を行ってはならない。売買・賃貸いずれの取引に関しても禁止。「予約」「先行案内」「モニター募集」等の名目も同様に禁止対象となる。",
    exp2: "許可・確認が下りた後であれば、完成前（建設・造成中）でも広告は可能。「未完成物件の広告＝全面禁止」ではなく、「許可取得前の広告が禁止」である点に注意。",
    exp3: "「許可取得後の未完成物件の広告はOK」。許可前と許可後（完成前）を混同しないこと。\n\n**覚え方** 「広告のGOサインは許可書が来てから。申請中は沈黙」。",
