    exp1: "宅建業法第36条により、宅建業者は、未完成物件について開発許可・建築確認等の処分を受ける前に、当該物件について売買契約・予約も含めて締結してはならない。広告禁止（33条）と同様の趣旨で、確認前の取引から消費者を保護する。",
    exp2: "広告開始時期の制限（33条）と契約締結時期の制限（36条）はセットで覚える。「広告も契約も、許可・確認が下りるまで禁止」が原則。",
    exp3: "「予約契約は本契約ではないので許可前でもOK」は誤り。予約・停止条件付き契約も禁止対象。\n\n**覚え方** 「広告33条・契約36条、どちらも許可前はストップ」。3と6、順番通り覚える。",
