    q: "次の状況に当てはまるのは？",
    choices: [{"text":"損害賠償額の予定と違約金の合計が代金の20%を超える特約は無効","correct":true},{"text":"当事者が合意すれば30%の違約金特約も有効","correct":false,"hint":"8種制限により、宅建業者が売主の場合は20%超の特約は無効。合意は関係ない。"}],
    exp1: "宅建業法第38条（8種制限の一つ）により、宅建業者が売主・非業者が買主の売買では、損害賠償額の予定額と違約金の合計が「代金の20%」を超える特約は、その超える部分が無効となる。民法では当事者合意があれば自由に設定できるが、宅建業法が特別規定として上書きする。",
    exp2: "「損害賠償額の予定＋違約金」の合計が20%以内なら有効。たとえば代金3000万円なら600万円以内が有効範囲。600万円を超えた部分は自動的に無効。",
    exp3: "「20%以内の違約金は有効」。20%という数値は絶対に覚える。手付額の制限（20%）と同じ数値なのでセットで記憶。\n\n**覚え方** 「損害賠償も違約金も、合わせて代金の20%が天井」。超えた分は紙切れ（無効）。",
