    exp1: "宅建業法第39条（8種制限）により、宅建業者が自ら売主の場合、手付金として代金の20%を超える額を受領することが禁止される。20%を超えた部分は無効となる（超えた部分のみ無効、契約全体が無効にはならない）。",
    exp2: "手付金は解約手付として機能することが多い（買主は手付放棄で解除・売主は手付倍返しで解除）。20%超を禁止することで買主の解除権行使を現実的に保障している。",
    exp3: "「手付額の制限（20%）は損害賠償額の予定制限（20%）と同じ数値だが別の条文」。混同しないよう両方の趣旨を理解する。\n\n**覚え方** 「手付は代金の20%まで。それ以上は受け取り禁止」。4000万円なら上限800万円。",
