    exp1: "宅建業法第33条の2（8種制限）により、宅建業者は自ら売主の場合、自己の所有に属しない宅地・建物について売買契約を締結してはならない。ただし例外として、①他人の物について確実に取得できる見込みがある場合、②未完成の自己所有物件の場合は許可・確認後に限り認められる。",
