    exp1: "宅建業法第40条（8種制限）により、宅建業者が自ら売主で非業者が買主の場合、目的物の契約不適合責任について「引渡しから2年以上」を下回る期間を設ける特約は無効となる（民法の規定より買主に不利な特約を禁止）。民法では「知った時から1年以内」が原則だが、買主保護のため宅建業法が上書き。",
