    exp3: "「勤務先が変わったら必ず登録を移さなければならない」と思い込みやすいが、登録はどの都道府県のままでも業務は可能。ただし実務上、現地の知事登録のほうが手続が便利なため移転するケースが多い。\n\n**覚え方** 「登録移転は転校ではなく転校届は任意」——住所が変わっても学籍を移さなくていい状況に近いイメージ。",
