    scenario: "賃貸オーナーの自分が、テナントの一人が認知症で判断能力がほぼない状態だと聞いた。家族が「成年後見人の申立てをする」と言っているが、後見人が選任されたら賃貸借契約の更新はどうなるのか確認したい。",
