    choices: [{"text":"成年後見人は成年被後見人に代わって財産管理・法律行為を行う権限を持つ","correct":true},{"text":"成年後見人は本人の意思に関係なく自由に財産を処分できる","correct":false,"hint":"後見人は被後見人の利益のために権限を行使する義務があり、恣意的処分は許されない。"}],
    exp1: "成年後見人は、精神上の障害により判断能力を欠く常況にある者（成年被後見人）について、家庭裁判所が選任する代理人。後見人は成年被後見人の財産を管理し、すべての法律行為を代理する権限を持つ。ただし居住用不動産の処分には家庭裁判所の許可が必要。",
    exp2: "試験では「後見人の権限（代理・取消）」「居住用不動産処分の許可要件（家裁の許可）」「後見人と保佐人・補助人の権限の違い」が頻出。後見人は同意権ではなく代理権を持ち、被後見人が単独で行った行為は（日用品購入を除き）取消可能という点を確認する。",
    exp3: "「成年後見人は何でも自由にできる」は誤り。居住用不動産（本人が住んでいる不動産）の売却・賃貸・担保設定には必ず家裁の許可が必要。許可なく行った処分は無効となる。\n\n**覚え方** 「後見人の大権＝代理権。ただし自宅処分は家裁の許可」——自宅だけは別格の保護あり。",
