    exp1: "被保佐人は精神上の障害により判断能力が著しく不十分な者で、家庭裁判所が保佐開始の審判をする。不動産の売買・担保設定・贈与・借財など民法13条に列挙された重要な財産行為には保佐人の同意が必要。同意なく行った重要行為は取り消すことができる。",
    exp2: "試験では「被保佐人の単独でできる行為の範囲（日常行為はOK・13条列挙行為は同意必要）」「取消権者（被保佐人本人・保佐人）」「成年被後見人との保護の程度の違い」が問われる。13条列挙行為を暗記する必要があるが、不動産売買・担保設定は必ず含まれる代表例。",
    exp3: "保佐人は被保佐人の代理権を当然には持たない（後見人と異なる）。代理権は家庭裁判所の審判で別途付与される。試験で「保佐人は常に代理できる」という選択肢は誤り。\n\n**覚え方** 「被保佐人＝重要行為に保佐人のGOサイン」——日常はOK、重要行為だけ同意が要る。",
