    exp1: "被補助人は精神上の障害により判断能力が不十分な者（軽度）で、家庭裁判所が補助開始の審判をする。補助人の同意が必要な行為は、民法13条1項に定める重要行為の範囲内で家庭裁判所が特定したものに限られる。被保佐人より保護の範囲が狭く、本人の自律性を尊重した制度設計。",
    exp2: "試験での出題頻度は低いが、4類型の比較問題の選択肢として登場する。被保佐人との違い（全13条列挙行為vs家裁が定めた特定行為）、補助人の代理権（家裁の審判で付与）、取消権者（被補助人本人・補助人）を確認しておく。",
    exp3: "「被補助人は軽度だから制限行為能力者ではない」は誤り。れっきとした制限行為能力者。ただし保護の程度が最も軽く、本人の申立て（または同意）がなければ補助開始の審判は行えない点が特徴。\n\n**覚え方** 「補助＝軽保護・特定行為のみ」——後見（全部）→保佐（13条全部）→補助（一部）と保護範囲が狭くなる。",
