    exp1: "相続分の譲渡とは、相続人が遺産分割前に自己の相続分（遺産全体に対する割合的持分）を他の相続人または第三者に譲渡することをいう。他の相続人の同意は不要で単独で行える。ただし他の相続人は、第三者への譲渡後1か月以内に取戻権（取戻し請求）を行使できる。",
    exp2: "試験では「相続分の譲渡の可否（可）」「他の相続人への譲渡と第三者への譲渡の違い（第三者への場合のみ取戻権あり）」「取戻権の期間（1か月以内）」が問われる。取戻権は第三者が相続に関与することを防ぐ趣旨の規定であり、他の相続人への譲渡では取戻権は生じない。",
    exp3: "「相続分の譲渡＝遺産の具体的財産の譲渡」ではない。相続分は遺産全体への割合的権利であり、譲渡後は譲受人が遺産分割協議の当事者になる。具体的財産の分配は遺産分割協議後。\n\n**覚え方** 「相続分は売れる・でも第三者譲渡は1か月以内に取り戻せる」——権利の流動性と取戻権をセットで覚える。",
