    q: "次の状況に当てはまるのは？",
    choices: [{"text":"市街化区域には、必ず用途地域が定められる","correct":true},{"text":"市街化区域には、用途地域を定める必要はない","correct":false,"hint":"市街化区域には必ず用途地域を定めなければならない。これは法律上の義務。"}],
    exp1: "市街化区域とは、すでに市街地を形成している区域、または概ね10年以内に優先的・計画的に市街化を図る区域のこと。市街化区域内には必ず用途地域（住居系・商業系・工業系の13種類）を定めなければならない。これが宅建試験で最も問われる市街化区域の特徴。",
    exp2: "「市街化区域には用途地域を必ず定める」という規定は試験頻出。対して市街化調整区域には原則として用途地域を定めない。非線引き区域・準都市計画区域には用途地域を定めることができる（義務ではない）という差異も整理する。",
    exp3: "「用途地域の指定が義務か任意か」は区域によって異なる。市街化区域だけが「必ず定める」義務あり。他の区域は「定めることができる」にとどまる。\n\n**覚え方** 「市街化区域＝積極的に街にする場所→必ず用途地域あり」。積極的な場所だから規制も明確。",
