    exp3: "「市街化調整区域の土地は安い→でも建物が建てられない可能性大」が実務上の落とし穴。試験では「原則制限・例外は限定列挙」という構造を理解する。\n\n**覚え方** 「調整区域＝ブレーキを踏んだ区域」。街に向けてアクセルを踏まない区域。",
