    exp1: "用途地域とは、都市計画法に基づき土地の利用目的を定めた13種類の地域区分。住居系（第1・2種低層住居専用、第1・2種中高層住居専用、第1・2種住居、準住居、田園住居）8種、商業系（近隣商業、商業）2種、工業系（準工業、工業、工業専用）3種。各地域で建築できる建物の種類が建築基準法により規制される。",
    exp2: "試験では「この建物はA用途地域に建てられるか」という用途制限の問題が頻出。特に注意すべきは「工業専用地域には住宅を建てられない」「第1種低層住居専用地域に店舗は建てられない（小規模を除く）」「田園住居地域の農産物直売所は建築可能」などの例外。",
