    exp3: "「特別用途地区」と「特定用途制限地域」の名称が紛らわしい。「内か外か」で完全に使い分ける。用途地域の中に上書きするのが「特別」、外側に初めて適用するのが「特定」。\n\n**覚え方** 「特別用途地区＝用途地域の中の特別ルール」。用途地域を前提にした上乗せ規制。",
