    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f8f9fa\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#333\">開発許可の面積基準</text>\n  <rect x=\"10\" y=\"35\" width=\"130\" height=\"28\" fill=\"#4a90d9\" rx=\"4\"/>\n  <text x=\"75\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">市街化区域</text>\n  <text x=\"210\" y=\"54\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#4a90d9\">1,000㎡以上</text>\n  <rect x=\"10\" y=\"72\" width=\"130\" height=\"28\" fill=\"#5cb85c\" rx=\"4\"/>\n  <text x=\"75\" y=\"91\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">非線引き区域</text>\n  <text x=\"210\" y=\"91\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#5cb85c\">3,000㎡以上</text>\n  <rect x=\"10\" y=\"109\" width=\"130\" height=\"28\" fill=\"#f0ad4e\" rx=\"4\"/>\n  <text x=\"75\" y=\"128\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">都市計画区域外</text>\n  <text x=\"210\" y=\"128\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#f0ad4e\">1万㎡以上</text>\n  <rect x=\"10\" y=\"146\" width=\"130\" height=\"28\" fill=\"#d9534f\" rx=\"4\"/>\n  <text x=\"75\" y=\"165\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">市街化調整区域</text>\n  <text x=\"210\" y=\"165\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#d9534f\">規模不問で許可必要</text>\n</svg>",
