    exp1: "津波防災地域づくりに関する法律（2011年制定）は、東日本大震災を踏まえ制定された法律で、津波による被害を防止・軽減するため、「津波防護施設」の整備・管理と「津波災害警戒区域」「津波災害特別警戒区域」（オレンジゾーン・レッドゾーン）の指定による土地利用規制を行う。レッドゾーン（特別警戒区域）内では住宅・社会福祉施設等の建築に都道府県知事の許可が必要。",
    exp2: "試験では「津波防災地域づくり法の目的」と「特別警戒区域内での建築規制の有無」が出題される程度。「警戒区域と特別警戒区域の違い（規制強度）」も基本知識として押さえる。警戒区域＝一定の情報提供・警戒義務、特別警戒区域＝建築許可制という規制の強弱が試験ポイント。",
    exp3: "出題頻度は低いが「法律の目的（津波被害防止）」と「規制対象（一定の開発行為・建築）」を混同しないこと。「津波防災＝海の話」「宅地造成等規制法＝山・斜面の話」と使い分ける。\n\n**覚え方** 「津波防災地域づくり法＝海辺の開発に待った！法。レッドゾーンは知事許可が必要な最強規制」。",
