    exp1: "生産緑地とは、市街化区域内にある農地等を都市農業の観点から保全するため、都市計画で定められる地域地区。指定を受けると原則として30年間は農地以外の行為が制限され、建築物の建築や宅地造成も原則禁止となる。農業従事者の死亡・農業継続困難となった場合は市区町村長へ買取申出が可能となる。",
    exp2: "試験では「買取申出ができる条件」と「30年経過後の申出」がポイント。30年経過前でも「農業の主たる従事者が死亡または農業継続困難な故障」の場合は買取申出できる。30年経過後は申出ができ、市区町村が申し出を受けてから1か月以内に買い取らない場合は指定が解除され宅地化が可能になる。",
    exp3: "「いつでも買取申出できる」は誤り。30年縛りと例外条件を確実に押さえる。特定生産緑地制度（2022年改正）も要注意。\n\n**覚え方:** 「生産緑地＝30年の農地ロック」。農業主従事者が死亡すれば鍵が開く。",
