    exp1: "開発許可の申請書には、開発区域の位置・区域・規模、予定建築物の用途、工事の設計・施工者、工事着手・完了予定年月日等を記載する。申請に際しては、排水施設に関して管理者の同意、道路管理者の同意、消防長・消防署長との協議等が必要となる。これらを怠ると申請が受理されない。",
    exp2: "試験では「誰の同意が必要か」「何を申請書に記載するか」が問われる。排水施設管理者・道路管理者の同意、消防との協議は頻出。知事の許可を受けた後に設計変更が生じた場合は変更許可または変更届出が必要になる点も押さえる。",
