    scenario: "マイホームを検討中の30代会社員の自分が、親から住宅購入資金として500万円を受け取ることになった。贈与税がかかるのか、住宅取得資金贈与の特例が使えるのか確認したい。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"贈与税の暦年課税では、1年間に受け取った財産の合計額から基礎控除110万円を差し引いた額が課税対象となる","correct":true},{"text":"贈与税の基礎控除は贈与者ごとに110万円が適用される","correct":false,"hint":"基礎控除110万円は受贈者1人あたりの年間控除額。複数の贈与者から受け取った場合もまとめて110万円まで非課税"}],
    exp1: "贈与税は、個人から財産の贈与を受けた場合に課される国税。暦年課税の場合、1月1日〜12月31日の1年間に受け取った贈与財産の合計額から基礎控除110万円を控除した残額に累進税率が適用される。相続時精算課税制度を選択した場合は累積2500万円まで特別控除が使え、超えた分は20%の税率で課税（2024年以降は毎年110万円の基礎控除も加算）。",
    exp2: "試験では「110万円の基礎控除（受贈者1人あたり・年間）」「暦年課税と相続時精算課税の違い」「住宅取得等資金の贈与特例（非課税枠の上乗せ）」が頻出。「贈与者ごとに110万円」は誤りで、受贈者が複数の贈与者から受け取っても年間合計で110万円の控除にとどまる。",
    exp3: "「贈与者ごとに110万円の控除」は誤り。受贈者（もらう側）1人に対し年間110万円が控除限度。親2人から各110万円もらっても合計220万円の贈与として計算する。\n\n**覚え方:** 「贈与税の110万円はもらう側が年1回使える切符。あげる側の数には連動しない」。",
