    cat: "税",
    freq: "high",
    diff: "mid",
    keyword: "1月1日・正常価格・固定資産評価額の約1.4倍",
    scenario: "不動産営業マンの自分が、顧客に「公示価格と実勢価格はどう違うの？」と質問された。固定資産評価額・路線価との関係も含めて、価格指標の全体像を説明しなければならない。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"公示価格は固定資産税評価額の約1.4倍、路線価（相続税評価額）の約1.25倍の水準とされている","correct":true},{"text":"公示価格は実勢価格（市場価格）と常に一致する","correct":false,"hint":"公示価格は正常価格（理論値）であり、実際の成約価格（実勢価格）とは必ずしも一致しない"}],
    exp1: "公示価格（地価公示法に基づく標準地の正常価格）は不動産の価格指標の基準とされる。各価格指標の水準目安：公示価格を100とすると、路線価（相続税評価額）は約80%、固定資産税評価額は約70%。実勢価格（市場での成約価格）は地域・需給によって公示価格の100〜130%程度まで幅がある。",
    exp2: "試験では「各価格指標の水準比較（公示100：路線価80：固定評価70）」「1月1日時点」「正常価格（通常の市場条件下）」が問われる。「公示価格＝実勢価格」は誤り。「固定資産評価額＝公示価格の70%水準」という数値も押さえる。",
    exp3: "「公示価格＝実勢価格」は誤り。公示価格は標準的な市場条件下の理論値。実際の取引は需給によって上下する。\n\n**覚え方:** 「公示100・路線価80・固定評価70。実勢は地域次第でばらつく」。",
