    exp3: "「宅建業者が売主でも買主でもある」ケースは試験での典型パターン。「業者間＝8種制限なし」という結論を即座に出せるよう訓練する。媒介は関係なく、売主が業者か否かで判断。\n\n**覚え方** 「業者同士の取引＝プロ同士＝消費者保護不要＝8種制限なし」。",
