    exp1: "宅建業者は専任媒介・専属専任媒介契約を締結した場合、依頼者に対して定期的に業務の処理状況を報告する義務を負う。専任媒介契約：2週間に1回以上。専属専任媒介契約：1週間に1回以上（より高い報告頻度）。報告方法は書面（または電磁的方法）で行う。一般媒介契約には業務報告義務の規定がない。",
    exp2: "試験では「専任2週間・専属専任1週間」という数字の対比が必出。専属専任の方が依頼者への拘束が強い分（自己発見取引も禁止）、業者の報告義務も重くなっている点が合理的に説明できる。報告義務の内容は「業務の処理状況の報告」であり、レインズへの登録状況・問い合わせ件数・内覧状況等が含まれる。報告を怠った場合は宅建業法違反となる。",
    exp3: "「一般媒介にも報告義務がある」は誤り。報告義務は専任系媒介のみ。専任と専属専任の数字（2週間・1週間）は逆に覚えないよう注意——専属専任の方が頻度が高い（1週間）。この数字は計算問題では出ないが、択一問題の核心となる。\n\n**覚え方** 「専任＝2週に1回、専属専任＝1週に1回——専属の方が密。専属は週報、専任は隔週報告」。",
