    q: "次の状況に当てはまるのは？",
    choices: [{"text":"指定流通機構（レインズ）への物件登録義務は売買・交換の専任系媒介に限られ、賃貸の媒介には義務がない","correct":true},{"text":"指定流通機構（レインズ）への物件登録は売買・賃貸のすべての媒介契約で義務付けられている","correct":false,"hint":"賃貸にはレインズ登録義務がない。売買・交換の専任・専属専任媒介のみが対象。"}],
    exp1: "指定流通機構（レインズ：Real Estate Information Network System）とは、国土交通大臣が指定した不動産流通の情報ネットワーク。登録された物件情報は全国の会員宅建業者が閲覧でき、売却の機会を広げる役割を担う。登録義務があるのは売買・交換の専任媒介（7日以内）と専属専任媒介（5日以内）。一般媒介と賃貸の媒介には登録義務がない。",
    exp2: "試験では「賃貸はレインズ登録義務なし」と「専任系媒介のみ義務」が頻出。レインズへの登録後は依頼者（売主）に登録証明書を交付する義務がある。また成約した場合は成約情報をレインズに登録（報告）することも義務付けられている（成約報告義務）。登録情報に虚偽記載をした場合は業務停止処分の対象。買主側の仲介業者はレインズを通じて物件情報を検索・取得できる（会員業者間の情報共有）。",
    exp3: "「レインズに登録すれば他の業者も買主を探してくれる」のはメリットだが、専属専任媒介の場合は依頼者（売主）が自己発見した買主との直接取引も禁止されている点に注意。レインズ登録義務と自己発見取引の可否は「一般・専任・専属専任」の3つで整理する必要がある。\n\n**覚え方** 「レインズ登録義務＝売買交換の専任系のみ。賃貸・一般媒介は義務なし」。",
