    q: "次の状況に当てはまるのは？",
    choices: [{"text":"未完成物件の場合、受領する手付金等が売買代金の5%または1000万円を超えるときに保全措置が義務となる","correct":true},{"text":"未完成物件の場合、受領する手付金等が売買代金の10%または1000万円を超えるときに保全措置が義務となる","correct":false,"hint":"10%は完成物件の基準。未完成物件は5%がしきい値。"}],
    exp1: "宅建業者が自ら売主となる未完成物件（建築工事完了前の宅地・建物）の売買において、手付金等として受領する額が「売買代金の5%超」または「1000万円超」のいずれかを超える場合に保全措置が義務付けられる。上記の例（代金4000万円・内金150万円）：150万円÷4000万円＝3.75%で5%未満、かつ150万円は1000万円以下→保全措置不要。",
    exp2: "試験では「完成物件10%・未完成物件5%」の違いをしっかり覚えたうえで計算問題を解く。未完成物件での計算例：代金3000万円・手付金200万円→200万円÷3000万円≒6.7%で5%超→保全必要。代金4000万円・手付金150万円→3.75%で5%未満かつ1000万円以下→保全不要。未完成物件の保全方法は銀行保証・保証保険の2方法のみ（指定保管機関による保管は不可）。",
    exp3: "「手付金等」には手付金だけでなく内金・中間金等、引渡し前に受け取るすべての金銭が含まれる。複数回に分けて受け取る場合は累計額で判断する。5%・1000万円のどちらか一方でも超えれば保全必要——「かつ」ではなく「または」であることに注意。\n\n**覚え方** 「未完成は5%（厳しめ）・完成は10%（ゆるめ）」。未完成の方が厳しい基準（5%）と覚える。",
