    exp1: "賃貸住宅管理業者は、管理受託契約を締結する前に委託者（オーナー）に対して管理受託契約の内容・条件に関する重要事項を記載した書面を交付し、説明する義務がある。説明は業務管理者（または一定の知識・経験を有する者）が行う。電磁的方法による交付も委託者の承諾があれば可能（2022年改正）。",
    exp2: "試験では「重要事項説明の相手がオーナーである点」と「契約前の説明という時期」が問われる。記載事項には①管理業務の内容・実施方法②報酬の額と支払時期③契約期間④更新・解除の条件⑤維持保全の業務内容等が含まれる。宅建業法35条（買主・借主への重要事項説明）と混同しないよう注意——相手と目的が異なる。",
    exp3: "「借主への説明義務」と混同しないことが重要。賃貸住宅管理の重要事項説明は管理委託（業者とオーナー間）の話であり、賃貸借（借主との関係）とは別の場面。宅建業者が媒介する際の借主への35条書面説明とは別制度。\n\n**覚え方** 「管理受託の重要事項説明＝オーナーに対して・契約前に・書面で——借主ではない」。",
