    exp3: "「省エネ基準への適合は任意」は2025年4月以降の新築には誤り。ただし既存建築物の改修や既存住宅の売買には義務的な省エネ改修の強制はない。35条書面での省エネ性能の説明義務（新設）はすべての取引に適用される。ZEH（ネット・ゼロ・エネルギー・ハウス）・長期優良住宅との関係も整理しておく。\n\n**覚え方** 「2025年4月から新築住宅は省エネ基準適合が原則義務——大規模だけでなく一般住宅も対象に拡大」。",
