    exp1: "都市計画法29条の開発許可制度は、宅地造成等の開発行為を規制し無秩序な市街化を防ぐ制度。開発許可申請に際して適合が審査される基準として、①技術基準（道路・排水施設・消防・公益施設等の設計が適切か）②立地基準（開発行為の場所が適切か——市街化調整区域での立地の特例等）がある。技術基準はすべての開発行為に適用されるが、立地基準は市街化調整区域での開発に主に適用される。",
    exp2: "試験では「技術基準と立地基準の違い」「市街化区域・市街化調整区域・非線引き区域・準都市計画区域での開発許可の要否」が問われる。開発許可が必要な面積基準：市街化区域は1,000m2以上（三大都市圏の一部は500m2以上）・市街化調整区域は規模にかかわらず全件許可必要・非線引き区域は3,000m2以上・準都市計画区域は3,000m2以上。",
    exp3: "「開発許可の技術基準さえ満たせば市街化調整区域でも自由に開発できる」は誤り。市街化調整区域では立地基準（用途・目的の適合性）も審査される。技術基準は形式的な設計基準、立地基準は実質的な開発の可否を判断する基準と理解する。\n\n**覚え方** 「開発許可の2つの基準：技術基準（設計が適切か）＋立地基準（場所が適切か）——市街化調整区域は両方クリアが必要」。",
