    exp1: "土地区画整理組合は、施行区域内の宅地所有者・借地権者7人以上が設立し、都道府県知事の認可を受けて成立する。組合設立の認可後、区域内の全宅地所有者・借地権者は自動的に組合員となる（強制加入）。組合は換地計画・資金計画を定め、事業を推進する。",
    exp2: "「設立要件」が試験頻出。宅地所有者・借地権者それぞれ3分の2以上の同意が必要。総会の議決事項・総代制度・組合解散の手続も出題される。また組合施行と個人施行の違い（個人は規模が小さく認可不要の場合あり）も確認しておく。",
    exp3: "組合員は賦課金・分担金の納付義務を負う。滞納の場合は強制徴収（地方税の例による）も可能。組合は法人格を持ち、施行者として換地処分権限を持つ。「組合員でなければ施行区域内の土地は持てない」とは異なり、非組合員の土地所有者もいる（公共用地・施行者保留地等）。\n\n**覚え方** 「3分の2の同意で設立、認可後は全員強制加入＝区画整理組合」。",
