    q: "次の状況に当てはまるのは？",
    choices: [{"text":"都市計画事業の認可・承認後は、事業地内で建物を建築するには都道府県知事等の許可が必要","correct":true},{"text":"都市計画事業が認可されても、事業地内の建築は自由に行える","correct":false,"hint":"事業認可後は建築制限がかかる。許可なく建築することはできない。"}],
    exp1: "都市計画事業とは、都市計画に基づいて行う都市計画施設の整備または市街地開発事業のこと（都市計画法59条）。国土交通大臣・都道府県知事の認可・承認を受けて施行される。認可・承認後は事業地内において土地の形質変更・建物建築等に都道府県知事等の許可が必要となる。",
    exp2: "「事業認可後の制限内容」が試験のポイント。許可を受けずに建築した場合、知事は移転・除却を命じることができる。また事業地内の土地・建物は施行者が収用（強制取得）できる。土地収用法の適用を受ける事業であれば、事業認定→収用裁決の手続が進む。",
    exp3: "都市計画施設予定地（事業認可前）でも、都市計画決定の段階で一定の建築制限がかかる。「都市計画決定段階の制限」と「事業認可後の制限」の2段階があることを区別して理解する。\n\n**覚え方** 「認可が下りたら事業地内は建築制限＝都市計画事業」。事業が始まったら勝手に建てられない。",
