    q: "次の状況に当てはまるのは？",
    choices: [{"text":"都市計画施設予定地内でも、階数2以下・地階なし・木造等の建築物は許可を受ければ建築できる","correct":true},{"text":"都市計画施設予定地内は建築が一切禁止される","correct":false,"hint":"一切禁止ではなく、許可基準を満たせば建築可能。ただし将来的に収用の対象になり得る。"}],
    exp1: "都市計画施設とは、都市計画において定められる道路・都市高速鉄道・公園・下水道・河川・学校・病院等の公共施設（都市計画法11条）。都市計画決定がされた「施設予定地」内では、階数3以上または地階のある建築物・容易に移転・除却できない建築物は原則として建築不可。",
    exp2: "「許可不要の例外」がない点に注意。予定地内の建築は必ず都道府県知事等の許可が必要で、許可基準（階数・構造）を満たさなければ許可されない。試験では「許可不要で建てられる建物の基準」として「2階建て以下・地階なし・木造等（容易に移転・除却できる構造）」を正確に覚える。",
    exp3: "「都市計画施設予定地」と「都市計画事業の事業地」は段階が違う。予定地は「計画は決まったが事業はまだ」の段階。事業地は「事業認可が下りた後」の段階。制限の強さは事業認可後の方が厳しい。\n\n**覚え方** 「予定地内は2階・地階なし・木造なら許可可＝都市計画施設」。3階建て・地下ありはNG。",
