    exp1: "市街地開発事業とは、都市計画法で定める面的整備事業の総称で、①土地区画整理事業②市街地再開発事業③住宅街区整備事業④防災街区整備事業⑤新住宅市街地開発事業⑥工業団地造成事業等が含まれる（都市計画法12条）。都市計画区域内の一定区域について、都市計画として決定される。",
    exp2: "「市街地再開発事業との違い」が試験で問われる。市街地再開発事業は老朽化した建物密集地を高度利用（高層化）して整備する。土地区画整理事業は宅地の整形・道路・公園の整備が目的。どちらも施行者・認可・換地（権利変換）の仕組みを持つが細部が異なる。",
