    exp1: "再開発等促進区とは、地区計画の区域内において、土地の合理的かつ健全な高度利用と都市機能の増進を図るために設ける区域（都市計画法12条の5）。通常の容積率制限を超えた容積率・壁面位置・用途の特例を定めることができ、老朽建物が密集するエリアの大規模再開発に活用される。",
