    exp1: "建物とは、土地に定着し、屋根・柱または壁を有する工作物をいう（建築基準法2条1号）。宅建業法でもこの概念を援用する。「定着性」「屋根・柱・壁の有無」が判断基準で、容易に撤去できる一時的な構造物は建物に含まれないことが多い。",
