    exp3: "建物か否かの判断は「土地定着性＋恒久的使用目的」が軸。形状だけで判断しないこと。\n\n**覚え方**\n「建物＝土地に根を張る・屋根と柱（壁）あり」。根っこが定着性、屋根が建物のシルエット。",
