    exp1: "重要事項の説明（宅建業法35条）は、宅建業者が取引の「相手方」に対して行う義務がある。売買では買主、賃貸では借主がその対象。売主・貸主は説明を受ける側ではない。ただし業者間取引（双方が宅建業者）では重要事項説明書の交付は必要だが説明は省略できる場合がある。",
    exp2: "「説明義務の相手方は誰か」が出題の核心。売主・貸主への説明は法的義務ではない。業者間取引での省略可否については「書面交付は省略不可・口頭説明は省略可」という整理が試験で問われる。",
    exp3: "「業者間取引では説明不要」と単純化しすぎないこと。書面（35条書面）の交付義務は業者間でも残る。説明（口頭）が省略できるだけ。\n\n**覚え方**\n「35条説明は買主（借主）へのプレゼント。売主（貸主）には渡さなくていい」。",
