    exp1: "IT重説（情報通信の技術を利用した重要事項説明）は、テレビ会議システム等の双方向通信手段を使って重要事項説明を行う方法。実施条件として、①相手方が事前に重要事項説明書等を受け取っていること、②映像・音声の双方向リアルタイム通信であること、③宅建士証を画面で確認できることが必要。",
